import{_ as x,o as i,f as l,a as e,b as s,t as a,w as r,a4 as I,n as T,J as f,K as w,O as D,r as A,e as d,C as _,c as L,g as F}from"./index-B75BQ2Ai.js";/* empty css               */import{p as P}from"./package-CsIDHiW1.js";const k=[{version:"1.8.0",date:"2026-10-18",zh:{title:"回收站、删除确认框与数据库长线铺路",items:["删除改为两步走：文件管理里删除文件（含目录、详情页删除、S3 / WebDAV 删除）先进入「回收站」（仅打标记，不动任何远端副本与外链配置），回收站里再次删除才会连远端副本一起彻底删除。误删可随时恢复。","删除文件前必须输入「确认删除」才能继续：文件管理单删、批量删、详情页删除、回收站彻底删除全部套用，防止误操作。","文件管理右上角新增「回收站」按钮（激活时红色高亮）：一键查看所有已删除文件（按删除时间倒序，最多 500 条），展示原文件名、大小、上传用户、删除时间与涉及的存储渠道；空回收站会有提示。再次点击退出并还原普通文件列表。","回收站支持批量操作：勾选多个文件后，底部浮动工具栏自动切换为「恢复 / 彻底删除」两个动作，可整批恢复或整批彻底删除。","回收站里的文件详情页动作变为「恢复 + 彻底删除」：下载、编辑、重命名、重定向、标签管理等不适用于已删除文件的按钮自动隐藏。","文件详情页的「文件分类」与「文件标签」链接改为新标签页打开（改用 URL 参数传参，不再依赖 sessionStorage，跨标签页可靠生效）。","页脚精简：移除「Powered by」后的图床名称与图标，仅保留版权年份、Powered by 与页脚自定义代码。","按用户 / 按 IP 的文件收集统计新增「上传渠道」列（含 WebDAV 上传），并支持点击文件封面直接打开该文件的详情页。","API Token 值在后台列表与凭据卡片中默认打码显示，点击右侧小眼睛临时查看，复制按钮仍复制完整值。","SQLite 开启 WAL 模式并设置 busy_timeout=5000 / synchronous=NORMAL：读写并发性能提升，偶发 database is locked 的概率大幅降低。","数据库长线铺路（不改变现有部署方式）：新增 schema.postgres.prisma（PostgreSQL 版数据结构）、tools/migrate-to-pg.ts（SQLite→PostgreSQL 一键迁移脚本，支持 --dry-run）与 docker-compose.pg.yml（PostgreSQL 16 编排），未来需要多人协作 / 多实例时按文档可平滑切换；同时发布《数据库规划》文档，明确八大业务系统的表布局、命名规范与版本升级数据兼容纪律。","安全自查与修复：上传响应、外链代理、Token 上传等入口对已删除文件全部返回 404；同名文件重新上传时被回收站占用的文件名会自动让位（旧记录彻底删除后新文件正常入库）。","修复主渠道副本的 isPrimary 标记从未写入的问题（一直依赖「第一条副本即主副本」的隐式约定）：新上传的主副本自动正确标记，存量文件由一次性脚本回填（tools/backfill-primary-copy.ts，每个文件最早创建的副本即主副本）；文件收集统计的「上传渠道」列按文件的全部有效副本聚合，主渠道与备份渠道都计入。"]},en:{title:"Trash bin, typed delete confirmation and database groundwork",items:["Deletes are now two-step: deleting files in File manager (folders, detail page, S3 and WebDAV included) moves them to a Trash bin (a soft-delete flag only — remote copies and link settings are untouched). Only deleting again inside the Trash removes the file together with its remote copies, permanently. Mistakenly deleted files can be restored at any time.",'Deleting now requires typing "confirm delete" in a dialog before it proceeds: single delete, batch delete, detail-page delete and Trash permanent delete all enforce it.',"File manager gains a Trash button in the top-right toolbar (highlighted red while active): it lists all soft-deleted files newest-first (up to 500), showing the original name, size, uploader, deletion time and the storage channels involved; an empty trash shows a hint. Clicking again exits and restores the normal list.","Trash supports batch actions: selecting multiple files switches the floating toolbar to Restore / Delete permanently, so a whole batch can be restored or purged at once.","In the Trash, the file detail dialog shows Restore and Delete permanently instead of Delete; buttons that make no sense for deleted files (download, edit, rename, redirect, tags) are hidden.","The Category and Tags links in the file detail dialog now open in a new tab (URL-parameter based instead of sessionStorage, so cross-tab navigation is reliable).",'Footer cleanup: the image-host name and icon after "Powered by" were removed; only the copyright years, "Powered by" and the footer custom code remain.',"File collection stats by user and by IP gain an Upload channels column (WebDAV uploads included), and clicking a file thumbnail now opens its detail dialog.","API Token values are masked by default in the admin list and credential card; a small eye button reveals them temporarily while the copy button still copies the full value.",'SQLite now runs in WAL mode with busy_timeout=5000 and synchronous=NORMAL: better read/write concurrency and far fewer sporadic "database is locked" errors.',"Database groundwork for the future (deployment unchanged): a schema.postgres.prisma (PostgreSQL structure), tools/migrate-to-pg.ts (one-command SQLite→PostgreSQL migration with --dry-run) and docker-compose.pg.yml (PostgreSQL 16 stack) are added, so switching when multi-user or multi-instance needs arrive is a documented, smooth path. A new Database planning document defines table layout, naming rules and upgrade compatibility discipline for eight planned subsystems.","Security review fixes: every entry point (upload responses, file proxy, token upload) returns 404 for soft-deleted files; re-uploading a file whose name is held by a trashed record now retires the trashed record automatically so the new file is stored correctly.",'Fixed the primary-copy flag that was never written (the system relied on an implicit "first copy is the primary" rule): new uploads now mark isPrimary correctly, and existing files were backfilled by a one-shot script (tools/backfill-primary-copy.ts — the earliest copy per file is the primary one); the Upload channels column of the collection stats now aggregates all active copies, counting both main and backup channels.']}},{version:"1.7.0",date:"2026-10-17",zh:{title:"内置本地存储渠道、文件详情跳转与一批交互打磨",items:["新增系统内置「本地存储」渠道（渠道列表排在最后）：无需任何配置即可上传，文件写入服务端自身 uploads 目录，零外部依赖、开箱即用。实体文件固定按「年份/月份」归档（如 uploads/2026/10/），与后台给文件设置的「文件分类」互相独立 —— 在文件管理里改分类只改数据库虚拟目录，不会搬运实体文件。该渠道固定使用渠道 ID 100000，不可删除、也不会出现在「添加渠道」候选里；库里一条启用的主渠道都没有时（全新安装，或把所有主渠道都取消了）会自动兜底为主渠道，只要已有主渠道就完全尊重你的设置、绝不抢占。","本地存储渠道的外链由本站 /file/ 统一代理下发，完整支持 Range（视频拖动进度条、音频 seek 正常）；同时修复「主渠道为本地存储时，补备份报『无法构造直链』」的问题（改为直接读盘取源文件）。","文件详情页的「文件分类」与「文件标签」改为可点击：点分类跳到文件管理的对应目录，点标签跳到文件管理并按该标签筛出文件。","修复文件详情页「编辑」时分类下拉为空、选不到已有目录的问题（目录树接口前缀写错成 /api/manage/directoryTree，正确为 /api/directoryTree）。","后台顶部固定功能栏（切换页面 / 夜间模式 / 语言）与移动端系统管理页的悬浮菜单：移除「滚动到页面底部就强制显示」的逻辑，改为纯方向驱动 —— 页面向上滚动显示、向下滚动隐藏，仅移动端生效的那部分保持仅移动端。","文件管理筛选器调整：「标签（含标签 / 未含标签）」从最下方移到「文件类型」之后；标签筛选弹窗里的标签按钮圆角由胶囊形改为 8px，并去掉点击后的聚焦边框。","移动端文件管理卡片模式：备份渠道简称角标此前未跟随主渠道一起缩小，显示得比主渠道更大；现已统一为同一字号与内边距。","登录页标题只显示图床名称（不再显示「登录到 xxx 图床」）；页脚的图床名称去掉链接，页脚传送门链接的颜色与字号改为与「Powered by」完全一致，仅保留超链接下划线、鼠标悬浮变蓝。","网页设置：公告输入框默认 4 行高、页脚传送门链接输入框默认 8 行高；「Logo 跳转链接」的占位提示改为项目仓库地址。","用户管理：「链接权限」改名为「外链权限」，「归集统计」改名为「文件收集统计」，并移除普通用户页面顶部「这里只显示你自己的账户，可修改自己的登录密码」的提示。","上传页「链接」标签页的图标由粘贴图标改为链接图标，与标签语义一致。","API Token「Web 通用」接入规则重构：移除 category / bucket / backup 三个请求参数；新增 username 与 userstore —— 传了 username 且 userstore 不为 false 时，按该账户在「用户管理」里绑定的主/备渠道上传并归属该账户；否则按 Token 配置的渠道、再兜底到全局渠道。文件分类改为统一走系统默认规则。","「Web 通用」Token 的 username 参数加了越权防护：Token 上绑定了具体账户时，只允许为该账户上传（传别人的账户名返回 403），账户不存在或已禁用返回 400；只有管理员 Token 可以代表任意账户上传。同时收紧本地存储的路径校验，被写脏的 remoteKey 也无法解析到 uploads 目录之外。","Docker 部署新增 uploads 数据卷（./data/uploads:/app/backend/uploads）：容器重建后本地存储渠道的文件不会丢失；.dockerignore 与生产包同步排除 uploads 目录，实体文件不会被误打进镜像或仓库。"]},en:{title:"Built-in local storage, detail-page navigation and a batch of interaction fixes",items:["New built-in Local Storage channel (always listed last): uploads work with zero configuration, writing files to the server's own uploads directory. Physical files are always archived by year/month (e.g. uploads/2026/10/), independent of the per-file Category in the admin UI — changing a file's category never moves bytes on disk. The channel always uses channel ID 100000, cannot be deleted and is not offered when adding a channel; if no enabled main channel exists (fresh install, or all main channels were cleared) it automatically becomes the fallback main channel, while any existing main channel is left untouched.",`Files in local storage are served through the site's own /file/ proxy with full Range support (video seeking works). Also fixed the case where adding a backup copy failed with "cannot build direct URL" when the main channel is local storage — it now reads from disk.`,"File details: the Category and Tags values are now clickable — clicking a category opens that folder in File manager, clicking a tag filters File manager by that tag.","Fixed the empty category dropdown when editing a file in File details (the directory-tree endpoint was called with the wrong prefix).",'Admin top bar and the mobile System settings floating menu: removed the "show again when reaching the bottom" behaviour. Visibility is now driven purely by scroll direction — show on scroll up, hide on scroll down (the mobile menu stays mobile-only).',"Filter menu: the Tags (has / no tags) section moved right after File type. Tag chips in the tag filter dialog use an 8px radius instead of a pill shape and no longer show a focus outline.","Mobile card view: the backup channel badge now shrinks together with the main channel badge instead of appearing larger.",'Login title now shows only the site name. The footer site name is plain text (no link); footer portal links inherit the exact colour and size of "Powered by", keeping only an underline and turning blue on hover.',"Page settings: the announcement field defaults to 4 rows, the footer portal link field to 8 rows; the Logo link placeholder now points at the project repository.",'User management: "Link access" renamed to "External link access", "Aggregation" renamed to "File collection stats", and the self-account hint was removed for regular users.',"The upload page's link tab now uses a link icon instead of a paste icon.",`API Token "Web generic" upload rules reworked: the category / bucket / backup parameters were removed; new username and userstore fields decide whether the account's bound channels are used (and the file is owned by that account), otherwise the token's channels and then the global channels apply. Upload category now always follows the system default rule.`,"The username parameter of Web generic tokens is now privilege-checked: a token bound to a specific account may only upload for that account (403 otherwise), and unknown or disabled accounts are rejected with 400; only admin tokens may act on behalf of any account. Local storage path validation was hardened so a tampered remoteKey can never resolve outside the uploads directory.","Docker deployment gains an uploads data volume (./data/uploads:/app/backend/uploads) so local-storage files survive container rebuilds; .dockerignore and the release bundle now exclude uploads, keeping physical files out of the image and the repository."]}},{version:"1.6.0",date:"2026-10-17",zh:{title:"目录重构：debug 调试与 dist 生产包分离",items:["全新目录结构：debug/ 存放前端源码、后端源码与工具脚本，dist/ 存放脱敏后的生产包，调试与交付彻底分开、互不干扰。","dist/ 变成自包含生产包：前后端各自的源码、构建产物、package.json / package-lock.json、Prisma schema 全部就位，不依赖 debug/ 中的任何文件，可直接构建镜像或上传仓库。","构建输出位置统一：前端 Vite 产物输出到 frontend/app，后端 tsc 产物输出到 backend/build，源码与产物不再混在同一层。","运行时路径探测重写：后端改为按「最近一个包含 package.json 的目录」定位自身，日志目录、.env、前端静态资源的查找不再依赖向上数目录层数，整体挪动目录也不会跑错位置。","新增 debug/tools/sync-dist.js：一条命令完成「构建 → 同步源码与产物 → 剔除 .env / 数据库 / 日志 / 压缩包」，并对 dist 做脱敏自检，发现敏感文件自动清除。","Docker 构建上下文改为 dist/：镜像内复用已构建的前端产物、重新编译后端，保证「源码 = 运行代码」；端口仍为 3618，SQLite 数据卷挂在 docker/data。","启动脚本拆分：start-windows.bat 运行调试版并自动同步 dist，sync-dist.bat 只负责打包，start-release.bat 用来验证生产包能否独立启动。","升级兼容：数据库结构来源仍为 backend/prisma/schema.prisma，启动时 db push 只新增不删除，旧版本数据库可直接沿用。"]},en:{title:"Directory refactor: debug/ for development, dist/ as the production bundle",items:["New layout: debug/ holds the frontend source, backend source and tooling; dist/ holds a sanitized production bundle. Development and delivery no longer interfere with each other.","dist/ is now self-contained: each side ships its own source, build output, package.json / package-lock.json and Prisma schema, with no dependency on debug/. It can be built into an image or pushed to git as-is.","Unified build output: Vite writes to frontend/app, tsc writes to backend/build, so source and artifacts no longer share a directory.","Rewritten runtime path resolution: the backend locates itself by finding the nearest directory containing package.json. Log directory, .env and static frontend assets no longer depend on counting parent levels, so moving the project cannot break them.","New debug/tools/sync-dist.js: one command builds, syncs source and artifacts, strips .env / databases / logs / archives, and runs a sanitization check that removes any leaked secrets.","Docker build context is now dist/: the image reuses the prebuilt frontend and recompiles the backend so that source always equals running code. Port 3618, SQLite volume at docker/data.","Split launchers: start-windows.bat runs the debug build and syncs dist, sync-dist.bat only packages, start-release.bat verifies the production bundle can start on its own.","Upgrade compatibility: schema still comes from backend/prisma/schema.prisma, and db push only adds tables and columns, so existing databases keep working."]}},{version:"1.5.0",date:"2026-10-17",zh:{title:"链接权限、标签筛选、上传提速与 48 位文件 ID",items:["用户管理新增「链接权限」开关：关闭后该账户上传的文件外链（/file/*）对外不可访问，后台预览与文件管理不受影响。","网页设置「页脚传送门链接」改为多行文本框，可直接粘贴 HTML / JS（统计代码、备案号、多条链接）；「隐藏页脚」与它一起迁入「页脚设置」分组。","后台左上角「系统管理 / 用户管理 / 文件管理」分类切换偶发不生效彻底修复：本地已有会话时立即跳转，会话校验放到后台静默执行。","归集统计对普通用户开放：普通用户只能使用「按用户归集」，且只统计自己账户下的文件。","渠道简称统一：简单图床 EI、兰空 LS、腾讯云 COS、阿里云 ALI、Immich IM、MinIO MI、R2 R2、S3 S3、WebDAV WD、自定义 Web DIY，由后端统一函数下发；文件管理卡片左上角的主渠道 / 备份渠道改为显示简称。","安全设置页一直转圈修复（组件里重复的 mounted 覆盖了加载逻辑，配置从未真正加载）。","系统状态左上角「运行状态」改为蓝色字体样式。","移动端文件管理「新建文件夹」按钮显示「＋」图标（原图标未注册字体库，移动端只剩空白）。","移动端点击后台左上方「目录选择」弹出的面板改为窗口居中显示。","上传文件生成的链接 ID 由 32 位随机值升级为 48 位（大小写字母 + 数字，拒绝采样避免取模偏差），显著提高遍历破解难度。","后台顶部固定功能栏（切换页面 / 夜间模式 / 语言）随页面滚动显隐：下滑隐藏，上滑或滚到页面底部立刻显示。","历史记录列表模式移除右侧删除按钮（需要删除请打开文件详情）。","文件详情页移除「AI 标签识别」。","文件详情页编辑标题、类型后立即刷新下方显示，无需刷新页面；编辑时还可重新选择文件分类目录（等同文件管理的移动）。","文件详情页「添加到黑名单 / 白名单」修复（此前调用了按 IP 的名单接口且方法不匹配，必然失败）。","后台文件管理封面不再显示标签（标签仍可在列表视图与文件详情查看）。","文件管理筛选新增「标签」项（含标签 / 未含标签）。","新增「标签筛选」按钮：弹窗列出已有标签与使用次数，可多选，选中为蓝色背景，并支持「或」（命中任一）与「且」（全部命中）切换。","搜索范围、上传用户两个下拉框收窄，下拉选项名称左右边距改为一致。","移动端文件详情页的链接格式那一行改为可左右滑动。","上传成功后异步自动打标签：文件类型、扩展名（不含点）、存储渠道类型简称、上传渠道、当前年份；异步执行，不影响上传速度。","上传速度优化：IP 归属地查询移出上传主链路（命中缓存即用，未命中落库后后台补写）、主渠道副本与文件记录合并为一次写入、备份渠道解析与上传计数全部后台化。","Docker 部署完善：镜像自带版本标记，首次启动只创建空库与必要配置（无任何测试数据），升级时自动补齐新增字段且不动已有数据。"]},en:{title:"Link access, tag filtering, faster uploads and 48-char file IDs",items:["User management gains a Link access switch: when off, public links (/file/*) of that account are blocked; admin preview stays available.","Web settings: Footer Portal Link is now a multi-line field accepting HTML / JS; it and Hide Footer moved into a dedicated Footer Settings group.","Fixed the intermittent no-op when switching System / Users / Files tabs: navigation is instant when a local session exists, and the session check runs silently in background.","Collection statistics are now available to normal users (per-user only, limited to their own account).","Unified channel abbreviations (EI / LS / COS / ALI / IM / MI / R2 / S3 / WD / DIY) served by one backend function; file cards show the abbreviation for main and backup channels.","Fixed the security settings page spinning forever (duplicate mounted hook overwrote the loader).","System status runtime badge now uses blue text styling.","Mobile New Folder button now shows a plus icon (previous icon was not registered).","Mobile directory picker is centered in the viewport.","File link IDs upgraded from 32 to 48 random characters (rejection sampling, no modulo bias).","Admin top bar hides on scroll down and reappears on scroll up or at page bottom.","Removed the delete button from the history list view.","Removed AI tag recognition from the file detail dialog.","Editing file name / type refreshes the detail immediately; the category folder can also be changed while editing.","Fixed blacklist / whitelist actions in file details (wrong endpoint and method before).","File management cards no longer show tags.","Filter dropdown gains a tags filter (has tags / no tags).","New tag filter dialog: lists existing tags with counts, multi-select with blue highlight, plus Any / All matching modes.","Narrowed the search-scope and uploader selects, with symmetric option padding.","Mobile file detail link-format tabs are horizontally scrollable.","Uploads are auto-tagged asynchronously (file type, extension, channel abbreviation, upload source, year) without slowing the upload.","Upload speed improvements: IP geolocation moved off the critical path, record and primary copy written in one transaction, backup resolution and counters backgrounded.","Docker deployment polish: versioned image, empty database with required settings only on first run, additive schema upgrades."]}},{version:"1.4.0",date:"2026-10-17",zh:{title:"文件详情全站统一、页脚自定义代码、会话有效期修复与一批界面优化",items:["「自定义 Web 通道」的图标徽标文字由「自定义」改为「DIY」。","文件详情页点击缩略图直接在新标签页打开文件链接。","文件详情全站统一封装：新增统一入口组件与统一加载函数，上传页、系统状态「最近上传」等处的详情弹窗与后台文件管理完全一致（同一模板、同一数据构造、同一套按钮与权限：下载 / 标签管理 / 黑名单 / 白名单 / 删除 / 编辑 / 重命名 / 重定向）。","系统状态「最近上传」点击规则：文件名和地址链接跳转历史记录页；分类文件夹跳转文件管理对应文件夹；文件类型（扩展名）打开文件链接；缩略图保持调出文件详情。","系统状态第二行文件统计新增「访问次数」，统计所有文件的访问总次数。","文件管理顶部工具栏新增「刷新」按钮：不刷新页面重新加载当前分类下的文件。","会话有效期修复：服务端会话过期时间此前硬编码 7 天，导致「设置 365 天仍会掉线」；现在与「安全设置 → 会话有效期」完全一致，配置 N 天即保持 N 天登录（除非清 Cookie 或手动退出），0 天表示永久。","单文件大小上限默认值改为 150MB（含前端兜底与设置占位说明）。","上传页右上角「更多菜单」按钮在移动端与左侧按钮保持一致大小。","移动端「目录选择」弹窗改为窗口居中显示（原底部抽屉改为居中弹窗）。","移动端上传页点击「上传目录」输入框时不再跳出空位（去掉聚焦时整体居中跳位的动作）。","「文件」模式上传列表的进度条旁同时显示文件大小（直接读本地文件信息，不增加等待）。","移动端后台系统管理悬浮菜单：收起态图标左右间距对称；页面下滑时隐藏、上滑或滚到底部时显示。","移动端用户管理「操作」列与 IP 归集「允许上传」列、安全设置 Token 管理「操作」列均取消固定，可随表格左右滚动。","用户管理：普通用户也能看到自己账户的「主渠道 / 备份渠道」值；归集统计的「按用户归集」仅管理员可见。","网页设置新增「页脚设置」分组：「隐藏页脚」与「页脚自定义代码」迁入其中；页脚代码改为多行文本，支持 HTML / JS 插入（如统计代码）。","上传设置页拆分为「上传数据设置」与「存储渠道管理」两个分区（插分割线）；每个存储分类标题栏右侧新增收缩按钮，可折叠 / 展开该分类下的渠道。","后台左上角分类切换偶发不生效的修复：路由会话探测加短缓存与超时兜底，后端瞬时繁忙时切换不再卡住。","清理全局提示中的历史变化类描述，只保留当下功能性说明。"]},en:{title:"Unified file details, custom footer code, session expiry fix and a batch of UI improvements",items:['The Custom Web channel badge text is now "DIY" instead of "Custom".',"Clicking the thumbnail in File Details opens the file link in a new tab.","File details unified site-wide: a single entry component and loader, so the dialog opened from the upload page / System Status matches admin file management exactly (same template, data builder, buttons and permissions).",'System Status "Recent uploads" click rules: name/link opens History; folder opens File Management in that folder; extension tag opens the file link; thumbnail still opens File Details.','A "Total views" badge was added to the file stats row in System Status.',"A Refresh button was added to the file-management toolbar to reload the current folder without a page reload.","Session expiry fix: the server-side session expiry was hardcoded to 7 days, so a 365-day setting still logged users out. It now follows the configured session days exactly (0 = permanent).","Default max upload size raised to 150MB.",'The mobile "More" button now matches the left-side button size.',"The mobile directory picker now shows as a centred dialog instead of a bottom drawer.","Tapping the upload folder input on mobile no longer leaves a phantom gap.","The upload progress bar now shows the file size alongside it.","Mobile floating admin menu: symmetric collapsed icon spacing; hides on scroll down, shows on scroll up or at page bottom.","Mobile: the Actions column in user management, the Allow-upload column in IP collection and the Token actions column are no longer frozen and scroll with the table.","User management: normal users now see their own main/backup channel values; per-user aggregation remains admin-only.",'Page settings gained a "Footer" group holding Hide-footer and Footer custom code; the code field is a textarea accepting HTML / JS (e.g. analytics).','Upload settings split into "Upload data" and "Channel management" sections with a divider; each channel group gained a collapse toggle.',"Fixed occasional top-left category switching failures: session probing now uses a short cache and timeout fallback.","Removed history-flavoured wording from user-facing tips; only functional descriptions remain."]}},{version:"1.3.0",date:"2026-10-16",zh:{title:"批量上传失败不阻塞循环重试、阿里云 OSS 渠道与一批界面修复",items:["批量上传失败不再阻塞队列：某个文件失败会跳过它、继续上传后面排队的文件，一波结束后回到失败队列整队再循环一轮，一直循环到全部成功。","每轮重试开始前都会重新获取一遍上传参数（默认存储渠道、备份渠道、上传目录、命名方式、外链前缀、允许格式与大小上限），重试期间在后台改了配置，下一轮立刻按新参数上传（对齐 CloudFlare-ImgBed 的机制）。","新增「阿里云 OSS」专用上传渠道：独立适配器实现 OSS V1 签名（只发 x-oss-date，与官方 ali-oss SDK 逐案比对一致），渠道选择、配置表单、图标与品牌色、摘要与提示全部补齐，共 10 种渠道类型。","上传页「默认」标签页改名为「文件」，现在是「文件」「链接」两个标签。","「文件」模式下的自动上传开关：只在开关右侧显示一个文案（开启＝自动、关闭＝手动），去掉了两侧多余的「手动 / 自动」标签。","后台文件管理卡片模式：鼠标移到文件封面显示手型（手指）光标。","修复上传页右上角「更多菜单」在移动端比左侧按钮高出一截、不在同一水平线的问题。","移动端后台系统管理页的左侧悬浮菜单缩小并改为悬浮在模块上方，不再挤占右侧模块的加载空间，模块恢复居中。","系统状态下的「上传趋势」「上传趋势分布」「上传用户分布」「文件状态分布」在移动端改为等比自适应缩小（含折线图字号与刻度自适应）。","上传完成后点击文件列表中的文件名可调出「文件详情」（与后台文件管理、历史记录共用同一弹窗与数据构造逻辑）。"]},en:{title:"Non-blocking batch retry loop, Aliyun OSS channel and a batch of UI fixes",items:["A failed file no longer blocks the batch: it is skipped and the rest of the queue keeps uploading; when the wave finishes the failed ones are retried as a group, looping until everything succeeds.","Before every retry round all upload params are re-fetched (default channel, backup channel, upload folder, naming, link prefix, allowed extensions and size limit), so backend changes take effect on the very next round (matching CloudFlare-ImgBed).","New dedicated Aliyun OSS channel: a standalone adapter implementing the OSS V1 signature (x-oss-date only, verified case-by-case against the official ali-oss SDK), with channel option, config form, icon/brand colour, summary and tips — 10 channel types in total.",'The upload page "Default" tab is renamed to "File", giving the "File" / "Link" pair.',"The auto-upload switch in File mode now shows a single label on its right (Auto when on, Manual when off); the redundant side labels are gone.","Admin file-management card view: the file cover now shows a pointer cursor on hover.",'Fixed the "More" menu on the upload page being misaligned (higher) than the left-side buttons on mobile.',"The floating side menu of the mobile admin page is smaller and floats above the module, no longer stealing loading space; modules are centred again.","The four System Status blocks (upload trend, trend distribution, uploader distribution, file status distribution) now scale proportionally on mobile, including chart fonts and tick counts.","After an upload finishes, clicking a file name in the list opens File Details (same dialog and data builder as admin file management and history)."]}},{version:"1.2.0",date:"2026-10-14",zh:{title:"图片尺寸处理、会话安全与一批界面与移动端修复",items:["图片尺寸处理正式实现：外链支持 ?width=&height=&fit= 参数实时缩放（sharp），支持「允许尺寸列表」白名单，302 模式忽略尺寸参数。","会话「Secure 模式」开关生效：HTTPS 访问时登录 Cookie 自动附加 Secure 标记。","登录页背景图改由管理端设置提供，客户端设置中的重复配置项已移除。","夜间模式自动取消背景图片加载，切回白天模式后自动恢复。","上传页：默认模式收缩态隐藏拖拽区左右边框，「自动上传」开关文案改为 自动 / 手动。","上传页链接模式：「转存」「外链」按钮的选中背景样式 PC 端与移动端保持一致。","上传页右上角更多菜单：修复移动端溢出提示文字导致的图标走位，移除与标签页重复的「粘贴上传」「文件上传」菜单项。","上传设置：编辑渠道时密钥自动回填明文（点小眼睛可查看完整值）；「自定义访问域名」输入框缩短并适配移动端。","修复管理员在用户管理编辑自己账户报「用户不存在」的问题（昵称 / 渠道 / 强制限制改存管理员档案）。","历史记录的文件详情补齐「标签」「黑名单」「白名单」三个按钮。","文件管理卡片模式：点击封面打开详情，左下角按钮改为打开文件链接，移除卡片删除按钮；历史记录卡片模式同步移除悬浮删除按钮。","移动端自适应：文件管理「全选」与排序操作行、系统管理悬浮菜单、系统状态各图表区域。","安全设置：WebDAV 说明文字并入上方表单，去掉独立说明框。","S3 接入批次补记：默认模式上传区样式对齐链接模式、文件列表区加宽、修复 S3 响应头非 ASCII 崩溃、补 DELETE /s3/* 支持、S3 用客户端 key 作为文件名。"]},en:{title:"Image resizing, session security and a batch of UI / mobile fixes",items:["Image resizing implemented: external links accept ?width=&height=&fit= and serve sharp-resized images, with an allowed-sizes whitelist; ignored in 302 mode.",'The session "Secure mode" toggle now works: cookies get the Secure flag automatically on HTTPS.',"Login page background now comes from the admin-side setting; the duplicate client-side option was removed.","Dark mode stops loading background images and restores them when switching back to light mode.","Upload page: collapsed dragger hides side borders; the auto-upload switch now reads Auto / Manual.","Transfer / external-link buttons share the same selected background style on desktop and mobile.","More menu: fixed mobile icon drift caused by overflowing hint text; removed menu items duplicated by the tab switcher.","Channel editing pulls plaintext secrets for the eye toggle; the custom access domain input is shortened and mobile-friendly.",'Fixed "user not found" when the admin edits their own account (profile fields now persist to the admin profile).',"File details from history now include tag / blacklist / whitelist buttons.","Card view: cover opens details, the bottom-left button opens the file link, card delete button removed (also in history).","Mobile layout fixes: select-all / sort rows, floating admin menu and status-page charts.","Security settings: WebDAV notes merged into the form.","S3 batch additions: default-mode styling aligned, wider file list, non-ASCII S3 header fix, DELETE /s3/* support, client-side key naming."]}},{version:"1.1.0",date:"2026-10-14",zh:{title:"账户体系、存储渠道收敛与设置页整理",items:["新增统一渠道入口：账户未指定存储渠道时回退到「上传设置」的全局主/备渠道，全站取渠道逻辑收敛到同一处。","文件详情统一为一套构造器，文件管理、历史记录、系统状态「最近上传」共用同一个详情弹窗。","普通用户权限细化：详情页按「可编辑 / 可删除」权限决定是否加载编辑、标签、重命名、重定向与删除按钮。","普通用户可修改自己的昵称；「用户端认证」密码也可用于登录普通用户账户（对外 WebDAV 仍只认账户密码）。","对外 WebDAV：跳过文件类型与大小限制；主/备渠道按接入授权账户解析；挂载信息增加「访问域名」。","Token 与上传设置的存储渠道、备份渠道下拉统一复用同一组件，备份渠道支持「默认 / none（不备份）/ 指定渠道」。","S3 协议接入的 Bucket 参数支持 auto 或留空，未指定或渠道无效时回落到默认存储渠道。","后台设置页整理：对外 WebDAV 功能块迁至安全设置「API Token 管理」下方，图片尺寸处理与上传相关配置迁至「其他设置」尾部。","文件管理卡片模式的备份标识只保留渠道简称；「链接格式」移除 TG File ID 与 S3 链接，普通用户不再显示该入口。","文件列表缓存按账户隔离，避免切换账户后刷新瞬间闪现非本人文件。","文件详情中任一字段超过 80 字符时，整体字号自动降一号。","系统状态「最近上传」记录增加分类信息列（上一版遗漏补记）。","新增本「版本修改日志」页面，系统状态页的版本卡片可直接跳转查看。"]},en:{title:"Account model, storage channel consolidation and settings cleanup",items:["Unified channel entry: falls back to the global main/backup channel when the account has none configured.","File details are built by a single shared builder used by file manager, history and status pages.","Per-user permissions: edit / tag / rename / redirect / delete buttons only load when the account is allowed to.","Regular users can change their own nickname; the user auth code can also sign in a regular user account (WebDAV still uses the account password only).","Public WebDAV: file type and size limits skipped; main/backup channels resolved from the authorized account; mount info now shows the access domain.","Token and upload settings share the same channel selector; backup channel supports Default / none / specific channel.",'S3 Bucket accepts "auto" or empty and falls back to the default storage channel.',"Settings reorganized: WebDAV block moved under API Token management, image resizing and upload defaults moved to Others.","Card backup badge shows the channel short name only; link format drops TG File ID and S3 link and is hidden for regular users.","File list cache is scoped per account to prevent leaking other users' files on refresh.","Detail dialog steps down one font size when any value exceeds 80 characters.","Recent-uploads list on the status page now shows the category column (added in this release).","Added this changelog page, reachable from the system version card."]}},{version:"1.0.0",date:"2026-09-30",zh:{title:"首个稳定版本",items:["统一账户体系：管理员与普通用户共用一个登录页，权限由账户角色决定。","三种上传链路：前端上传页、API-Web / API-S3 Token 接入、对外 WebDAV 挂载。","九种存储渠道：COS、MinIO、R2、S3 兼容、WebDAV、Immich、EasyImages、Lsky Pro 与自定义 Web 通道。","主渠道同步上传 + 备份渠道异步双写，支持批量补备份与去重。","文件管理支持分类目录、标签、黑白名单、重定向、批量操作与卡片/列表两种视图。"]},en:{title:"First stable release",items:["Unified account model: one login page for admins and regular users.","Three upload paths: web uploader, API-Web / API-S3 tokens, and public WebDAV mounts.","Nine storage channel types including COS, MinIO, R2, S3-compatible, WebDAV, Immich, EasyImages, Lsky Pro and a custom web channel.","Synchronous main channel plus asynchronous backup channel, with batch backup and deduplication.","File manager with categories, tags, white/black lists, redirects, batch actions and card/list views."]}}];var y;(y=k[0])!=null&&y.version;const z={name:"ChangelogPage",computed:{isZh(){return String(this.$i18n.locale||"zh-CN").startsWith("zh")},zh(){return this.isZh},version(){return P.version},entries(){return k.map(n=>{var c,h,u,g;return{version:n.version,date:n.date,title:this.isZh?(c=n.zh)==null?void 0:c.title:(h=n.en)==null?void 0:h.title,items:(this.isZh?(u=n.zh)==null?void 0:u.items:(g=n.en)==null?void 0:g.items)||[]}})}},methods:{toggleLocale(){D(this.isZh?"en":"zh-CN")},goBack(){window.history.length>1?this.$router.back():this.$router.push("/")}}}